import javax.swing.*;import java.awt.*;import java.sql.SQLException;import java.util.*;
/** Display-only feature switches. Values and percentage rules are maintained under Deductions. */
public class FeatureSettingsPanel extends JPanel {
 public FeatureSettingsPanel(){setLayout(new BorderLayout());PayrollSettingsDAO dao=new PayrollSettingsDAO();PayrollSettings settings=dao.load();JPanel list=new JPanel();list.setBorder(BorderFactory.createEmptyBorder(20,25,20,25));list.setLayout(new BoxLayout(list,BoxLayout.Y_AXIS));Map<String,JCheckBox> checks=new LinkedHashMap<>();for(Map.Entry<String,PayrollSettings.Component> e:settings.getComponents().entrySet()){JCheckBox c=new JCheckBox(e.getKey(),e.getValue().enabled);c.setFont(new Font("SansSerif",Font.PLAIN,16));c.setAlignmentX(LEFT_ALIGNMENT);checks.put(e.getKey(),c);list.add(c);list.add(Box.createVerticalStrut(6));}JButton save=new JButton("Save Display Options");save.addActionListener(x->{for(Map.Entry<String,JCheckBox> e:checks.entrySet())settings.getComponents().get(e.getKey()).enabled=e.getValue().isSelected();try{dao.save(settings);JOptionPane.showMessageDialog(this,"Display options saved.");}catch(SQLException ex){JOptionPane.showMessageDialog(this,"Could not save options: "+ex.getMessage());}});JPanel b=new JPanel(new FlowLayout(FlowLayout.RIGHT));b.add(save);add(new JScrollPane(list),BorderLayout.CENTER);add(b,BorderLayout.SOUTH);}
}
